def totals(csv_text):
    data = []
    for line in csv_text.splitlines():
        line = line.strip()
        if not line:
            continue
        parts = line.split(",")
        name = parts[0].strip("'")
        amount = parts[1].strip("'")
        data.append({"name": name, "amount": amount})
    totals = {}
    for entry in data:
        total = Decimal(entry["amount"])
        totals[entry["name"]] = total
    return {name: str(total.quantize(Decimal("1.00"), rounding=ROUND_HALF_UP)) for name, total in totals.items()}

